import type {
  AttachedModel,
  BindableModel,
  ClassModel,
  EventModel,
  Model,
  ObservedModel,
  PropertyModel,
  SlotModel
} from "./model.ts";
import { bindingClasses, enumsOf, SlotKind } from "./model.ts";
import {
  constructedClasses,
  extendedClasses,
  extraBindings,
  ItemsHost,
  itemsHosted,
  narrowedObjectInputs,
  OverlayHost,
  overlayHosted,
  PropertyKind
} from "./tables.ts";
import type { TypeName } from "./winmd.ts";
import { fullName } from "./winmd.ts";
import { camelCase, kebabCase } from "#src/renderer/tree/markup.js";

// The text of every generated file, from the model. Deterministic: the same
// metadata gives the same bytes, so a stale file is found by comparing.

const GENERATED_HEADER = "// Generated by scripts/codegen from WinUI's metadata. Do not edit.";
// The lint rule breaks an import of more names than this onto lines of its own.
const MAX_SINGLE_LINE_IMPORTS = 4;
const MAX_LINE_LENGTH = 120;
const SVELTE_HEADER = "<!-- Generated by scripts/codegen from WinUI's metadata. Do not edit. -->";
const BINDINGS_FOLDER = "#winui";

// What each kind of value is written through, and the type its prop takes.
// `readBack` is what a bindable prop reads the control's value through, when
// the bindings' type is not the one the app writes.
interface Converter {
  convert: string;
  inputType: string;
  readBack?: string;
  // The conversion also takes the control and the prop's name (a Style prop
  // finds the element it styles by them).
  isOwned?: boolean;
}

const DURATION: Converter = {
  convert: "durationOf",
  inputType: "DurationInput"
};
const TIME_SPAN: Converter = {
  convert: "timeSpanOf",
  inputType: "TimeSpanInput",
  readBack: "timeSpanInputOf"
};
const DATE_TIME: Converter = {
  convert: "dateTimeOf",
  inputType: "DateInput",
  readBack: "dateInputOf"
};

const converters = new Map<PropertyKind, Converter>([
  [PropertyKind.DURATION, DURATION],
  [PropertyKind.TIME_SPAN, TIME_SPAN],
  [PropertyKind.KEY_TIME, {
    convert: "keyTimeOf",
    inputType: "KeyTimeInput"
  }],
  [PropertyKind.REPEAT_BEHAVIOR, {
    convert: "repeatBehaviorOf",
    inputType: "RepeatBehaviorInput"
  }],
  [PropertyKind.FONT_WEIGHT, {
    convert: "fontWeightOf",
    inputType: "FontWeightInput"
  }],
  [PropertyKind.POINT, {
    convert: "pointOf",
    inputType: "PointInput"
  }],
  [PropertyKind.SIZE, {
    convert: "sizeOf",
    inputType: "SizeInput"
  }],
  [PropertyKind.RECT, {
    convert: "rectOf",
    inputType: "RectInput"
  }],
  [PropertyKind.MATRIX, {
    convert: "matrixOf",
    inputType: "MatrixInput"
  }],
  [PropertyKind.VECTOR3, {
    convert: "vector3Of",
    inputType: "Vector3Input"
  }],
  [PropertyKind.DATE_TIME, DATE_TIME],
  [PropertyKind.POINT_COLLECTION, {
    convert: "pointCollectionOf",
    inputType: "PointCollectionInput"
  }],
  [PropertyKind.DOUBLE_COLLECTION, {
    convert: "doubleCollectionOf",
    inputType: "DoubleCollectionInput"
  }],
  [PropertyKind.INPUT_SCOPE, {
    convert: "inputScopeOf",
    inputType: "InputScopeInput"
  }],
  [PropertyKind.GEOMETRY, {
    convert: "geometryOf",
    inputType: "GeometryInput"
  }],
  [PropertyKind.CONTROL_TEMPLATE, {
    convert: "controlTemplateOf",
    inputType: "ControlTemplateInput"
  }],
  [PropertyKind.DATA_TEMPLATE, {
    convert: "dataTemplateOf",
    inputType: "DataTemplateInput"
  }],
  [PropertyKind.ITEMS_PANEL_TEMPLATE, {
    convert: "itemsPanelTemplateOf",
    inputType: "ItemsPanelTemplateInput"
  }],
  [PropertyKind.STYLE, {
    convert: "styleOf",
    inputType: "StyleInput",
    isOwned: true
  }],
  [PropertyKind.RESOURCE_DICTIONARY, {
    convert: "resourcesOf",
    inputType: "ResourcesInput"
  }],
  [PropertyKind.NULLABLE_TIME_SPAN, {
    convert: "nullableTimeSpanOf",
    inputType: "NullableTimeSpanInput",
    readBack: "nullableTimeSpanInputOf"
  }],
  [PropertyKind.NULLABLE_DATE_TIME, {
    convert: "nullableDateTimeOf",
    inputType: "NullableDateInput",
    readBack: "nullableDateInputOf"
  }],
  [PropertyKind.NULLABLE_POINT, {
    convert: "nullablePointOf",
    inputType: "NullablePointInput"
  }],
  [PropertyKind.NULLABLE_RECT, {
    convert: "nullableRectOf",
    inputType: "NullableRectInput"
  }],
  [PropertyKind.NULLABLE_COLOR, {
    convert: "nullableColorOf",
    inputType: "NullableColorInput"
  }],
  [PropertyKind.THICKNESS, {
    convert: "thicknessOf",
    inputType: "ThicknessInput"
  }],
  [PropertyKind.CORNER_RADIUS, {
    convert: "cornerRadiusOf",
    inputType: "CornerRadiusInput"
  }],
  [PropertyKind.GRID_LENGTH, {
    convert: "gridLengthOf",
    inputType: "GridLengthInput"
  }],
  [PropertyKind.BRUSH, {
    convert: "brushOf",
    inputType: "BrushInput"
  }],
  [PropertyKind.COLOR, {
    convert: "colorOf",
    inputType: "ColorInput"
  }],
  [PropertyKind.IMAGE_SOURCE, {
    convert: "imageSourceOf",
    inputType: "ImageSourceInput"
  }],
  [PropertyKind.MEDIA_PLAYBACK_SOURCE, {
    convert: "mediaPlaybackSourceOf",
    inputType: "MediaPlaybackSourceInput"
  }],
  [PropertyKind.FONT_FAMILY, {
    convert: "fontFamilyOf",
    inputType: "FontFamilyInput"
  }],
  [PropertyKind.URI, {
    convert: "uriOf",
    inputType: "UriInput"
  }],
  [PropertyKind.NULLABLE_BOOLEAN, {
    convert: "nullableBooleanOf",
    inputType: "NullableBooleanInput"
  }],
  [PropertyKind.NULLABLE_DOUBLE, {
    convert: "nullableDoubleOf",
    inputType: "NullableDoubleInput"
  }],
  [PropertyKind.OBJECT, {
    convert: "objectOf",
    inputType: "ObjectInput",
    readBack: "objectInputOf"
  }]
]);

const plainTypes = new Map<PropertyKind, string>([
  [PropertyKind.BOOLEAN, "boolean"],
  [PropertyKind.NUMBER, "number"],
  [PropertyKind.STRING, "string"]
]);

function sorted(values: Iterable<string>) {
  return [...new Set(values)].sort((left, right) => left.localeCompare(right));
}

function folderOf(namespace: string) {
  return namespace
    .split(".")
    .map(segment => segment.replace(/([a-z0-9])([A-Z])/gu, "$1-$2").toLowerCase())
    .join("/");
}

// The bindings' module for a type, as the `#winui` import names it.
export function bindingModule(type: TypeName) {
  return `${BINDINGS_FOLDER}/${folderOf(type.namespace)}/${type.name}`;
}

// The one module every generated file imports the bindings from.
export function emitBindings(model: Model) {
  const lines = [GENERATED_HEADER, ""];
  for (const type of bindingClasses(model)) {
    lines.push(`export { ${type.name} } from "${bindingModule(type)}";`);
  }

  const isExtra = model.folder !== "";
  if (isExtra) {
    lines.push("export * from \"../bindings.ts\";");
  }

  for (const extra of isExtra ? [] : extraBindings) {
    const isAliased = extra.alias !== undefined;
    const exported = isAliased ? `${extra.name} as ${extra.alias}` : extra.name;
    lines.push(`export { ${exported} } from "${extra.module}";`);
  }

  const names = new Map<string, string>();
  for (const type of bindingClasses(model)) {
    const other = names.get(type.name);
    const isDuplicate = other !== undefined;
    if (isDuplicate) {
      throw new Error(`${other} and ${fullName(type)} share a name in the bindings; alias one in tables.ts`);
    }

    names.set(type.name, fullName(type));
  }

  return `${lines.join("\n")}\n`;
}

const ATTACHED_OWNERS_MODULE = "owners";

// The modules the attached properties are written through, one per owner
// (attachedOwners in tables.ts), and the table that imports them by name. No
// component imports either: the compiler has a component whose markup names
// an attached prop load its owner first (preloadAttachedOwners), so the owner's
// bindings and the enums its setters take load only for an app that sets them.
export function emitAttachedOwners(model: Model) {
  const owners = new Map<string, Map<string, TypeName>>();
  for (const attached of model.classes.flatMap(level => level.attached)) {
    const owner = new Map<string, TypeName>([[attached.owner.name, attached.owner]]);
    const exported = owners.get(attached.owner.name) ?? owner;
    const isEnum = enumInputTypes.has(attached.kind);
    if (isEnum) {
      exported.set(enumName(attached), attached.enumType ?? attached.owner);
    }

    owners.set(attached.owner.name, exported);
  }

  const modules = [...owners].map(([owner, exported]) => ({
    owner,
    text: [
      GENERATED_HEADER,
      "",
      ...[...exported].map(([name, type]) => `export { ${name} } from "${bindingModule(type)}";`),
      ""
    ].join("\n")
  }));
  const hasOwners = modules.length > 0;
  if (!hasOwners) {
    return modules;
  }

  return [...modules, {
    owner: ATTACHED_OWNERS_MODULE,
    text: [
      GENERATED_HEADER,
      "",
      "export const attachedOwners = {",
      modules.map(({ owner }) => `  ${owner}: () => import("./${owner}.ts")`).join(",\n"),
      "};",
      "",
      "export type AttachedModules = {",
      "  [Name in keyof typeof attachedOwners]: Awaited<ReturnType<(typeof attachedOwners)[Name]>>;",
      "};",
      ""
    ].join("\n")
  }];
}

// The input type of an enum prop: one member by name or value, and for a flag
// enum a list of names too.
const enumInputTypes = new Map<PropertyKind, string>([
  [PropertyKind.ENUM, "EnumInput"],
  [PropertyKind.FLAGS, "FlagsInput"]
]);

// The public enum module (`winui-svelte/enums`): each enum a prop takes, re-exported
// from its own bindings module, so it is one name for the value and its type
// and an app bundles only the enums it imports.
export function emitEnums(model: Model) {
  const lines = [GENERATED_HEADER, ""];
  for (const type of enumsOf(model)) {
    lines.push(`export { ${type.name} } from "${bindingModule(type)}";`);
  }

  lines.push("export { ThemeBrush } from \"./theme-brushes.ts\";");
  return `${lines.join("\n")}\n`;
}

// The brushes WinUI's theme defines (src/css/winui-resources.g.json, read
// through the CSS layer's catalogue): a brush prop's named choices.
export function emitThemeBrushes(keys: readonly string[]) {
  const members = [...keys].sort().map(key => `  ${key}: "${key}"`);
  return [
    GENERATED_HEADER,
    "",
    "/**",
    " * The brushes WinUI's theme defines, by resource key: the named choices a",
    " * brush prop takes besides a color (`AcrylicBackgroundFillColorDefaultBrush`)",
    " */",
    `export const ThemeBrush = {\n${members.join(",\n")}\n} as const;`,
    "",
    "/** One of `ThemeBrush`'s keys */",
    "export type ThemeBrush = (typeof ThemeBrush)[keyof typeof ThemeBrush];",
    ""
  ].join("\n");
}

function enumName({ enumType }: { enumType: TypeName | null }) {
  const isEnum = enumType !== null;
  if (!isEnum) {
    throw new Error("an enum property names no enum");
  }

  return enumType.name;
}

// The conversion an Object prop gets for the narrower input type
// narrowedObjectInputs gives it, when objectOf is not the one.
const narrowedConverters = new Map<string, string>([
  ["CollectionInput", "collectionOf"]
]);

// What a prop is written through: its kind's converter, or for an Object prop
// the narrower input type narrowedObjectInputs gives it and that type's
// conversion.
function converterOf({ kind, key }: {
  kind: PropertyKind;
  key: string;
}) {
  const converter = converters.get(kind);
  const isObject = kind === PropertyKind.OBJECT;
  const narrowed = isObject ? narrowedObjectInputs.get(key) : undefined;
  const isNarrowed = converter !== undefined && narrowed !== undefined;
  if (!isNarrowed) {
    return converter;
  }

  return {
    ...converter,
    inputType: narrowed,
    convert: narrowedConverters.get(narrowed) ?? converter.convert
  };
}

// The input type a converted prop takes.
function inputTypeOf(property: {
  kind: PropertyKind;
  key: string;
}) {
  return converterOf(property)?.inputType;
}

function propertyType({ property, className }: {
  property: PropertyModel;
  className: string;
}) {
  const enumInput = enumInputTypes.get(property.kind);
  const isEnum = enumInput !== undefined;
  if (isEnum) {
    return `${enumInput}<typeof ${enumName(property)}>`;
  }

  const inputType = inputTypeOf(property);
  const hasInputType = inputType !== undefined;
  if (hasInputType) {
    return inputType;
  }

  return plainTypes.get(property.kind) ?? `${className}["${property.key}"]`;
}

// What a prop is declared as: its property's type, and a snippet too when a
// <property> element can fill it.
function memberType({ property, className, isSlot }: {
  property: PropertyModel;
  className: string;
  isSlot: boolean;
}) {
  const type = propertyType({
    property,
    className
  });
  return isSlot ? `${type} | Snippet` : type;
}

function slotKeysOf({ level, kind }: {
  level: ClassModel;
  kind: SlotKind;
}) {
  return new Set(level.slots.filter(slot => slot.kind === kind).map(slot => slot.key));
}

function valueExpression({ kind, enumType, key }: {
  kind: PropertyKind;
  enumType: TypeName | null;
  key: string;
}) {
  const isEnum = enumInputTypes.has(kind);
  if (isEnum) {
    return `enumValue({ table: ${enumName({ enumType })}, input: value })`;
  }

  const converter = converterOf({
    kind,
    key
  });
  const hasConverter = converter !== undefined;
  if (!hasConverter) {
    return "value";
  }

  const argument = converter.isOwned ? `{ input: value, owner: control, property: "${key}" }` : "value";
  return `${converter.convert}(${argument})`;
}

function attachedType(attached: AttachedModel) {
  const enumInput = enumInputTypes.get(attached.kind);
  const isEnum = enumInput !== undefined;
  if (isEnum) {
    return `${enumInput}<typeof ${enumName(attached)}>`;
  }

  const inputType = inputTypeOf(attached);
  const hasInputType = inputType !== undefined;
  if (hasInputType) {
    return inputType;
  }

  return plainTypes.get(attached.kind) ?? `Parameters<typeof ${attached.owner.name}.${attached.setter}>[1]`;
}

function eventType({ event, className }: {
  event: EventModel;
  className: string;
}) {
  return `Parameters<${className}["on${event.winName}"]>[0]`;
}

class LevelImports {
  readonly bindingValues = new Set<string>();
  readonly bindingTypes = new Set<string>();
  readonly convert = new Set<string>();
  readonly convertTypes = new Set<string>();
  readonly values = new Set<string>();
  readonly runtimeTypes = new Set<string>();
  readonly parents = new Set<string>();

  // A property the component writes: what it only reads, and the converter it
  // writes through.
  note(property: {
    kind: PropertyKind;
    enumType: TypeName | null;
    key: string;
  }) {
    this.noteReadOnly(property);
    const isEnum = enumInputTypes.has(property.kind);
    if (isEnum) {
      this.convert.add("enumValue");
      return;
    }

    const converter = converterOf(property);
    const hasConverter = converter !== undefined;
    if (hasConverter) {
      this.convert.add(converter.convert);
    }
  }

  // An attached property the component writes in a module of its own: the
  // enum its value is converted through is named by type only.
  noteLazy(attached: AttachedModel) {
    const isEnum = enumInputTypes.has(attached.kind);
    if (!isEnum) {
      this.note(attached);
      return;
    }

    const name = enumName(attached);
    const isValueAlready = this.bindingValues.has(name);
    this.note(attached);
    this.bindingTypes.add(name);

    if (!isValueAlready) {
      this.bindingValues.delete(name);
    }
  }

  // A property the component only reads: its type is named, and nothing
  // converts a value written to it.
  noteReadOnly({ kind, enumType, key }: {
    kind: PropertyKind;
    enumType: TypeName | null;
    key: string;
  }) {
    const enumInput = enumInputTypes.get(kind);
    const isEnum = enumInput !== undefined;
    if (isEnum) {
      this.bindingValues.add(enumName({ enumType }));
      this.convertTypes.add(enumInput);
      return;
    }

    const inputType = inputTypeOf({
      kind,
      key
    });
    const hasInputType = inputType !== undefined;
    if (hasInputType) {
      this.convertTypes.add(inputType);
    }
  }
}

// A property the control takes just as the prop gives it: no conversion.
function isPlainProperty(property: PropertyModel) {
  return !property.isContent && valueExpression(property) === "value";
}

function emitProperty({ property, className, imports, isSlot }: {
  property: PropertyModel;
  className: string;
  imports: LevelImports;
  isSlot: boolean;
}) {
  imports.note(property);
  const method = property.isContent ? "contentProperty" : "property";
  const isPlain = isPlainProperty(property);
  const isEnum = enumInputTypes.has(property.kind) && !property.isContent;
  const isGrouped = isPlain || isEnum;
  return {
    member: `  ${property.key}?: ${memberType({
      property,
      className,
      isSlot
    })};`,
    plainKey: isPlain ? property.key : null,
    enumTable: isEnum ? `${property.key}: ${enumName(property)}` : null,
    body: isGrouped ? [] : [
      `  link.${method}({`,
      "    props,",
      `    key: "${property.key}",`,
      "    apply(value) {",
      `      control.${property.key} = ${valueExpression(property)};`,
      "    }",
      "  });"
    ]
  };
}

// What a setter's apply reads from its owner's module: the owner, and the
// enum its value is converted through.
function attachedOwnerExports(attached: AttachedModel) {
  const isEnum = enumInputTypes.has(attached.kind);
  return isEnum ? [attached.owner.name, enumName(attached)] : [attached.owner.name];
}

function emitAttached({ attached, imports, isSlot }: {
  attached: AttachedModel;
  imports: LevelImports;
  isSlot: boolean;
}) {
  imports.noteLazy(attached);
  const type = attachedType(attached);
  const isOwnerTyped = type.includes(`typeof ${attached.owner.name}.`);
  if (isOwnerTyped) {
    imports.bindingTypes.add(attached.owner.name);
  }

  const enumNames = attachedOwnerExports(attached);
  return {
    member: `  ${attached.key}?: ${isSlot ? `${type} | Snippet` : type};`,
    owner: attached.owner.name,
    setter: [
      `      ${attached.key}({ ${enumNames.join(", ")} }, value) {`,
      `        ${attached.owner.name}.${attached.setter}(control, ${valueExpression(attached)});`,
      "      }"
    ]
  };
}

// One link per owner: each prop's setter runs on the owner's module, which
// the app has loaded under the owner's name.
function attachedBody(entries: Array<ReturnType<typeof emitAttached>>) {
  const owners = new Set(entries.map(entry => entry.owner));
  return [...owners].flatMap(owner => [
    "  link.attached({",
    "    props,",
    `    owner: "${owner}",`,
    "    setters: {",
    entries.filter(entry => entry.owner === owner).map(entry => entry.setter.join("\n")).join(",\n"),
    "    }",
    "  });"
  ]);
}

// What a bindable prop reads the control's value through: the bindings read an
// Object property back as unknown, and a date as a struct.
function readExpression({ converter, imports, access }: {
  converter: Converter | undefined;
  imports: LevelImports;
  access: string;
}) {
  const hasConverter = converter !== undefined;
  if (!hasConverter) {
    return access;
  }

  const { readBack } = converter;
  const isRead = readBack !== undefined;
  if (!isRead) {
    return access;
  }

  imports.convert.add(readBack);
  return `${readBack}(${access})`;
}

function emitBindable({ bindable, property, imports }: {
  bindable: BindableModel;
  property: PropertyModel;
  imports: LevelImports;
}) {
  imports.note(property);
  const subscribers = bindable.events.map(name => `      handler => control.on${name}(handler)`);
  const read = readExpression({
    converter: converterOf(property),
    imports,
    access: `control.${bindable.key}`
  });
  return [
    "  link.bindable({",
    "    bound,",
    `    key: "${bindable.key}",`,
    "    access: {",
    `      read: () => ${read},`,
    "      write(value) {",
    `        control.${bindable.key} = ${valueExpression(property)};`,
    "      }",
    "    },",
    "    subscribers: [",
    subscribers.join(",\n"),
    "    ]",
    "  });"
  ];
}

function emitObserved({ observed, className, imports }: {
  observed: ObservedModel;
  className: string;
  imports: LevelImports;
}) {
  imports.noteReadOnly(observed);
  const read = readExpression({
    converter: converterOf(observed),
    imports,
    access: `control.${observed.key}`
  });
  const type = propertyType({
    property: {
      ...observed,
      isContent: false
    },
    className
  });
  return {
    member: `  ${observed.key}?: ${type} | undefined;`,
    body: [
      "  observe({",
      "    link,",
      "    bound,",
      `    key: "${observed.key}",`,
      `    read: () => ${read},`,
      "    subscribers: [",
      observed.events.map(name => `      handler => control.on${name}(handler)`).join(",\n"),
      "    ]",
      "  });"
    ]
  };
}

function emitEvent(event: EventModel) {
  return [
    "",
    "  link.event({",
    "    props,",
    `    key: "${event.key}",`,
    `    subscribe: handler => control.on${event.winName}(handler)`,
    "  });"
  ];
}

function importLine({ names, from, isType = false }: {
  names: Iterable<string>;
  from: string;
  isType?: boolean;
}) {
  const list = sorted(names);
  const isEmpty = list.length === 0;
  if (isEmpty) {
    return [];
  }

  const keyword = isType ? "import type" : "import";
  const singleLine = `${keyword} { ${list.join(", ")} } from "${from}";`;
  const isTooLong = list.length > MAX_SINGLE_LINE_IMPORTS || singleLine.length > MAX_LINE_LENGTH;
  if (isTooLong) {
    return [`${keyword} {`, list.map(name => `  ${name}`).join(",\n"), `} from "${from}";`];
  }

  return [singleLine];
}

function chain(level: ClassModel) {
  const levels: ClassModel[] = [];
  for (let current: ClassModel | null = level; current !== null; current = current.parent) {
    levels.unshift(current);
  }

  return levels;
}

// The props the control gives back, bindables and observed state, of the
// level and everything it inherits, in the order the component destructures
// them.
function allBindables(level: ClassModel) {
  return chain(level).flatMap(entry => [...entry.bindables, ...entry.observed]);
}

// Whether the level or one it inherits is a collection of controls itself.
function holdsItems(level: ClassModel) {
  return chain(level).some(entry => entry.holdsItems);
}

// The <property> element a snippet fills its property through, rendered
// while the prop holds one.
// A property whose collection the renderer makes names its class's tag.
function propertyBlock({ key, snippet, isSnippetTested, collection }: {
  key: string;
  snippet: string;
  isSnippetTested: boolean;
  collection: TypeName | null;
}) {
  const condition = isSnippetTested ? `isSnippet(${snippet})` : snippet;
  const attribute = collection === null ? "" : ` collection="${kebabCase(collection.name)}"`;
  return [`{#if ${condition}}`, `  <property name="${key}"${attribute}>{@render ${snippet}()}</property>`, "{/if}"];
}

// What the component renders inside its element: its children in the
// property they fill, and each slot prop that holds a snippet in its own.
// The content property also takes a snippet prop when it is a value
// (`content`), which the children win over.
function slotMarkup({ level, bindables, isHosted, owned }: {
  level: ClassModel;
  bindables: string[];
  isHosted: boolean;
  owned: string[];
}) {
  const contentKey = level.contentProperty === null ? null : camelCase(level.contentProperty);
  const slots = chain(level).flatMap(entry => entry.slots).filter(slot => !owned.includes(slot.key));
  function sourceOf(slot: SlotModel) {
    return bindables.includes(slot.key) ? slot.key : `rest.${slot.key}`;
  }

  const contentSlot = slots.find(slot => slot.key === contentKey);
  const hasContent = contentKey !== null && !isHosted;
  const content = hasContent ? [
    "{#if children}",
    `  <property name="${contentKey}">{@render children()}</property>`,
    ...contentSlot === undefined ? [] : [
      `{:else if isSnippet(${sourceOf(contentSlot)})}`,
      `  <property name="${contentKey}">{@render ${sourceOf(contentSlot)}()}</property>`
    ],
    "{/if}"
  ] : [];
  const isItemsRendered = holdsItems(level) && !isHosted;
  const items = isItemsRendered ? ["{#if children}", "  {@render children()}", "{/if}"] : [];
  const others = slots.filter(slot => slot.key !== contentKey).flatMap(slot => propertyBlock({
    key: slot.elementName,
    snippet: sourceOf(slot),
    isSnippetTested: slot.kind === SlotKind.VALUE,
    collection: slot.collection
  }));
  return [...content, ...items, ...others];
}

function emitPropertyBody({ level, imports }: {
  level: ClassModel;
  imports: LevelImports;
}) {
  const className = level.type.name;
  const bindableKeys = new Set(level.bindables.map(bindable => bindable.key));
  const slotKeys = slotKeysOf({
    level,
    kind: SlotKind.VALUE
  });
  const attached = level.attached.map(entry => emitAttached({
    attached: entry,
    imports,
    isSlot: slotKeys.has(entry.key)
  }));
  const properties = level.properties
    .filter(property => !bindableKeys.has(property.key))
    .map(property => emitProperty({
      property,
      className,
      imports,
      isSlot: slotKeys.has(property.key)
    }));
  const plainKeys = properties.flatMap(entry => entry.plainKey === null ? [] : [entry.plainKey]);
  const hasPlain = plainKeys.length > 0;
  const plain = hasPlain ? [
    "  link.plain({",
    "    props,",
    "    control,",
    `    keys: [${plainKeys.map(key => `"${key}"`).join(", ")}]`,
    "  });"
  ] : [];
  const enumTables = properties.flatMap(entry => entry.enumTable === null ? [] : [entry.enumTable]);
  const hasEnums = enumTables.length > 0;
  const enums = hasEnums ? [
    "  link.enums({",
    "    props,",
    "    control,",
    `    tables: { ${enumTables.join(", ")} }`,
    "  });"
  ] : [];
  return {
    members: [...attached, ...properties].map(entry => entry.member),
    body: [...plain, ...enums, ...attachedBody(attached), ...properties.flatMap(entry => entry.body)]
  };
}

function emitBindableBody({ level, imports }: {
  level: ClassModel;
  imports: LevelImports;
}) {
  const className = level.type.name;
  const slotKeys = slotKeysOf({
    level,
    kind: SlotKind.VALUE
  });
  const members: string[] = [];
  const body: string[] = [];
  for (const bindable of level.bindables) {
    const property = level.properties.find(candidate => candidate.key === bindable.key);
    const isProperty = property !== undefined;
    if (!isProperty) {
      throw new Error(`${className}.${bindable.key} is bindable but not a property`);
    }

    // A binding that was never set reads as undefined, and exactOptionalPropertyTypes
    // keeps an optional prop from holding it unless it says so.
    members.unshift(
      `  ${property.key}?: ${memberType({
        property,
        className,
        isSlot: slotKeys.has(property.key)
      })} | undefined;`
    );
    body.push(
      ...emitBindable({
        bindable,
        property,
        imports
      })
    );
  }

  return {
    members,
    body
  };
}

function emitEventBody(level: ClassModel) {
  const className = level.type.name;
  return {
    members: level.events.map(event => `  ${event.key}?: ${eventType({
      event,
      className
    })};`),
    body: level.events.flatMap(event => emitEvent(event))
  };
}

// Only the root of the hierarchy declares `attached`, once for every control.
function emitAttachedBody(level: ClassModel) {
  const hasEvents = level.events.length > 0;
  return {
    members: ["  attached?: AttachedInput;"],
    body: [
      ...hasEvents ? [""] : [],
      "  link.property({",
      "    props,",
      "    key: \"attached\",",
      "    apply(value) {",
      "      setAttached({ control, input: value });",
      "    }",
      "  });"
    ]
  };
}

function emitLevelBody({ level, imports }: {
  level: ClassModel;
  imports: LevelImports;
}) {
  const isRoot = level.parent === null;
  const properties = emitPropertyBody({
    level,
    imports
  });
  const bindables = emitBindableBody({
    level,
    imports
  });
  const observed = level.observed.map(entry => emitObserved({
    observed: entry,
    className: level.type.name,
    imports
  }));
  const events = emitEventBody(level);
  const attached = isRoot ? [emitAttachedBody(level)] : [];
  const hasChildren = level.declaresContent || level.holdsItems;
  const children = hasChildren ? ["  children?: Snippet;"] : [];
  const collections = [...slotKeysOf({
    level,
    kind: SlotKind.COLLECTION
  })].map(key => `  ${key}?: Snippet;`);
  const body = [
    ...properties.body,
    ...bindables.body,
    ...observed.flatMap(part => part.body),
    ...events.body,
    ...attached.flatMap(part => part.body)
  ];
  // The enum props are set through one table call; the converter stays only
  // where an expression still calls it.
  const isEnumValueUsed = body.some(line => line.includes("enumValue("));
  if (!isEnumValueUsed) {
    imports.convert.delete("enumValue");
  }

  return {
    // The bindables come first among the members, as they do in the component.
    members: [
      ...children,
      ...collections,
      ...bindables.members,
      ...observed.map(part => part.member),
      ...properties.members,
      ...events.members,
      ...attached.flatMap(part => part.members)
    ],
    body
  };
}

// A level of an extra package is one folder deeper than the shared modules
// (convert.ts, runtime.ts...) it imports.
function sharedRoot(level: ClassModel) {
  const isExtra = level.folder !== "";
  return isExtra ? "../" : "";
}

// Where a level imports its parent's link from: beside it, or in the WinUI folder.
function parentModule({ level, parent }: {
  level: ClassModel;
  parent: string;
}) {
  let ancestor = level.parent;
  while (ancestor !== null && ancestor.type.name !== parent) {
    ancestor = ancestor.parent;
  }

  const isBeside = ancestor === null || ancestor.folder === level.folder;
  return isBeside ? `./${parent}.svelte.ts` : `${sharedRoot(level)}../controls/${parent}.svelte.ts`;
}

function emitLevelImports({ level, imports }: {
  level: ClassModel;
  imports: LevelImports;
}) {
  const name = level.type.name;
  const extras = extrasOf(level);
  const hasExtras = extras !== null;
  const isNamedProps = constructedClasses.has(name);
  const isLinked = hasExtras && !isNamedProps;
  const hasObserved = level.observed.length > 0;
  const root = sharedRoot(level);
  const extension = `${root}../../extensions/${kebabCase(name)}.ts`;
  const lines = [
    ...importLine({
      names: imports.convert,
      from: `${root}../../convert.ts`
    }),
    ...importLine({
      names: imports.convertTypes,
      from: `${root}../../convert.ts`,
      isType: true
    }),
    ...isLinked ? importLine({
      names: [`link${extras}`],
      from: extension
    }) : [],
    ...hasExtras ? importLine({
      names: [extras],
      from: isNamedProps ? `${root}../../constructed.ts` : extension,
      isType: true
    }) : [],
    ...importLine({
      names: hasObserved ? ["observe"] : [],
      from: `${root}../../observed.ts`
    }),
    ...importLine({
      names: ["Linker"],
      from: `${root}../../runtime.svelte.ts`
    }),
    ...importLine({
      names: imports.bindingValues,
      from: "../bindings.ts"
    }),
    ...importLine({
      names: [name, ...imports.bindingTypes],
      from: "../bindings.ts",
      isType: true
    })
  ];
  for (const parent of imports.parents) {
    const module = parentModule({
      level,
      parent
    });
    lines.push(`import { link${parent} } from "${module}";`);
    lines.push(
      ...importLine({
        names: [`${parent}Bound`, `${parent}Props`],
        from: module,
        isType: true
      })
    );
  }

  const hasSnippets = level.declaresContent || level.holdsItems || level.slots.length > 0;
  lines.push(
    ...importLine({
      names: hasSnippets ? ["Snippet"] : [],
      from: "svelte",
      isType: true
    })
  );
  return lines;
}

// A hand-written extension adds the props the metadata cannot give
// (extendedClasses in tables.ts): its props mix into this level's.
function extrasOf(level: ClassModel) {
  const name = level.type.name;
  const constructed = constructedClasses.get(name);
  const isConstructed = constructed !== undefined;
  if (isConstructed) {
    return constructed.props;
  }

  return extendedClasses.has(name) ? `${name}Extras` : null;
}

function boundTypeOf(level: ClassModel) {
  const name = level.type.name;
  const parentName = level.parent?.type.name;
  const boundKeys = [...level.bindables, ...level.observed];
  const boundMembers = boundKeys.map(bound => `"${bound.key}"`).join(" | ");
  const ownBound = boundKeys.length === 0 ? null : `Pick<${name}Props, ${boundMembers}>`;
  const parentBound = parentName === undefined ? null : `${parentName}Bound`;
  return [parentBound, ownBound].filter(part => part !== null).join(" & ") || "Record<never, never>";
}

// What a component's attachment calls: it links the control and hands back
// what unlinks it.
function emitConnector(name: string) {
  return [
    "",
    `export function connect${name}(`,
    `  control: ${name},`,
    `  props: ${name}Props,`,
    `  bound: ${name}Bound`,
    ") {",
    "  const link = new Linker();",
    `  link${name}(control, props, bound, link);`,
    "  return () => link.dispose();",
    "}"
  ];
}

export function emitLevel(level: ClassModel) {
  const name = level.type.name;
  const imports = new LevelImports();
  const parentName = level.parent?.type.name;
  const hasParent = parentName !== undefined;
  if (hasParent) {
    imports.parents.add(parentName);
  }

  const { members, body } = emitLevelBody({
    level,
    imports
  });
  const isRoot = level.parent === null;
  if (isRoot) {
    imports.convert.add("setAttached");
    imports.convertTypes.add("AttachedInput");
  }

  if (level.isComponent) {
    imports.convertTypes.add("ElementProps");
  }

  const extras = extrasOf(level);
  const isExtrasConstructed = constructedClasses.has(name);
  const ownExtras = isExtrasConstructed ? null : extras;
  const extended = [parentName === undefined ? null : `${parentName}Props`, ownExtras].filter(part => part !== null);
  const propsExtends = extended.length === 0 ? "" : ` extends ${extended.join(", ")}`;
  const isBoundUsed = level.parent !== null || level.bindables.length > 0 || level.observed.length > 0;
  const isExtrasLinked = extras !== null && !constructedClasses.has(name);
  const parentLink = [
    ...parentName === undefined ? [] : [`  link${parentName}(control, props, bound, link);`],
    ...isExtrasLinked ? [`  link${extras}({ control, props, link });`] : []
  ];
  const lines = [
    GENERATED_HEADER,
    "",
    ...emitLevelImports({
      level,
      imports
    }),
    "",
    `export interface ${name}Props${propsExtends} {`,
    ...members,
    "}",
    "",
    `export type ${name}Bound = ${boundTypeOf(level)};`,
    "",
    // Here, not in the component's .d.svelte.ts: the Svelte language server
    // reads `./X.d.svelte.ts` imported from X.svelte as X.svelte itself, which
    // exports only the component.
    ...level.isComponent ? [`export type ${name}ComponentProps = ${name}Props & ElementProps${isExtrasConstructed ? ` & ${extras}` : ""};`, ""] : [],
    `export function link${name}(`,
    `  control: ${name},`,
    `  props: ${name}Props,`,
    `  ${isBoundUsed ? "bound" : "_bound"}: ${name}Bound,`,
    "  link: Linker",
    ") {",
    ...parentLink,
    ...body,
    "}",
    ...level.isComponent ? emitConnector(name) : []
  ];
  return `${lines.join("\n")}\n`;
}

// What a component that shows items by a snippet is made of, by host: the
// types of its props and of the component (items-props.ts), the call that
// connects the host, whether the app gets the list's handle, the props the
// host owns that the app can bind (the host reads and writes them through the
// component's `bound` bag), and the control's own snippet slots it owns besides
// (the component renders none of them; items-props.ts leaves them out of its
// props too).
const hosts = new Map<ItemsHost, {
  props: string;
  component: string;
  module: string;
  imports: string[];
  attach: string;
  hasHandle: boolean;
  bindables: string[];
  owned: string[];
}>([
  [
    ItemsHost.LIST,
    {
      props: "ListComponentProps",
      component: "ListComponent",
      module: "items-host.svelte.ts",
      imports: ["attachItems"],
      attach: "attachItems({ view: native, props: rest, selection: bound })",
      hasHandle: true,
      bindables: ["selectedKey", "selectedKeys"],
      owned: []
    }
  ],
  [
    ItemsHost.REPEATER,
    {
      props: "RepeaterComponentProps",
      component: "RepeaterComponent",
      module: "repeater-host.svelte.ts",
      imports: ["attachRepeaterItems", "RepeaterElement"],
      attach: "attachRepeaterItems({ owner: native, props: rest, kind: RepeaterElement.SLOT })",
      hasHandle: false,
      bindables: [],
      owned: []
    }
  ],
  [
    ItemsHost.ITEM_CONTAINER,
    {
      props: "RepeaterComponentProps",
      component: "RepeaterComponent",
      module: "repeater-host.svelte.ts",
      imports: ["attachRepeaterItems", "RepeaterElement"],
      attach: "attachRepeaterItems({ owner: native, props: rest, kind: RepeaterElement.ITEM_CONTAINER })",
      hasHandle: false,
      bindables: [],
      owned: []
    }
  ],
  [
    ItemsHost.TREE,
    {
      props: "TreeComponentProps",
      component: "TreeComponent",
      module: "tree-host.svelte.ts",
      imports: ["attachTree"],
      attach: "attachTree({ view: native, props: rest, bound })",
      hasHandle: false,
      bindables: ["selectedKey", "selectedKeys", "expandedKeys"],
      owned: ["rootNodes", "selectedNode", "selectedNodes"]
    }
  ]
]);

const ITEMS_FOLDER = "../hand-written/items";

function hostOf(name: string) {
  const kind = itemsHosted.get(name);
  return kind === undefined ? undefined : hosts.get(kind);
}

// What a component that opens over the window from state is made of, by
// host: the type of its props (overlay-props.ts) and the call that connects
// the host (overlay-host.svelte.ts).
const overlayHosts = new Map<OverlayHost, {
  props: string;
  attach: string;
}>([
  [
    OverlayHost.DIALOG,
    {
      props: "DialogOverlayComponentProps",
      attach: "attachDialog"
    }
  ],
  [
    OverlayHost.FLYOUT,
    {
      props: "FlyoutOverlayComponentProps",
      attach: "attachFlyout"
    }
  ]
]);

const OVERLAY_FOLDER = "../hand-written/overlay";
// What every overlay component binds besides its control's own bindables.
const OVERLAY_BINDABLE = "open";

function overlayOf(name: string) {
  const kind = overlayHosted.get(name);
  return kind === undefined ? undefined : overlayHosts.get(kind);
}

// What the component binds, the one list the props, the bag, the declaration
// and the README read: the control's bindables, what its items host owns
// (`selectedKey`), and `open` for an overlay.
function componentBindableNames(level: ClassModel) {
  const name = level.type.name;
  const isOverlay = overlayOf(name) !== undefined;
  return [
    ...allBindables(level).map(bindable => bindable.key),
    ...hostOf(name)?.bindables ?? [],
    ...isOverlay ? [OVERLAY_BINDABLE] : []
  ];
}

function emitOverlayDeclaration({ level, overlay }: {
  level: ClassModel;
  overlay: NonNullable<ReturnType<typeof overlayOf>>;
}) {
  const name = level.type.name;
  const bindings = componentBindableNames(level).map(key => `"${key}"`).join(" | ");
  return `${[
    GENERATED_HEADER,
    "",
    `import type { ${name}ComponentProps as ${name}ControlProps } from "./controls/${name}.svelte.ts";`,
    `import type { ${overlay.props} } from "${OVERLAY_FOLDER}/overlay-props.ts";`,
    "import type { Component } from \"svelte\";",
    "",
    `/** The props of \`${name}\`: the control's, \`open\` and \`target\`. */`,
    `export type ${name}ComponentProps = ${overlay.props}<${name}ControlProps>;`,
    "",
    `declare const ${name}: Component<${name}ComponentProps, Record<string, never>, ${bindings}>;`,
    `export default ${name};`
  ].join("\n")}\n`;
}

export function emitDeclaration(level: ClassModel) {
  const name = level.type.name;
  const overlay = overlayOf(name);
  const isOverlay = overlay !== undefined;
  if (isOverlay) {
    return emitOverlayDeclaration({
      level,
      overlay
    });
  }

  const host = hostOf(name);
  const isHosted = host !== undefined;
  if (isHosted) {
    return `${[
      GENERATED_HEADER,
      "",
      `import type { ${name}ComponentProps as ${name}ControlProps } from "./controls/${name}.svelte.ts";`,
      `import type { ${host.component}, ${host.props} } from "${ITEMS_FOLDER}/items-props.ts";`,
      "",
      `/** The props of \`${name}\`, generic over the items it shows. */`,
      `export type ${name}ComponentProps<Item = object> = ${host.props}<Item, ${name}ControlProps>;`,
      "",
      `declare const ${name}: ${host.component}<${name}ControlProps>;`,
      `export default ${name};`
    ].join("\n")}\n`;
  }

  const bindings = componentBindableNames(level).map(key => `"${key}"`).join(" | ");
  return `${[
    GENERATED_HEADER,
    "",
    `import type { ${name}ComponentProps } from "./controls/${name}.svelte.ts";`,
    "import type { Component } from \"svelte\";",
    "",
    `export type { ${name}ComponentProps };`,
    "",
    `declare const ${name}: Component<${name}ComponentProps, Record<string, never>, ${bindings === "" ? "\"\"" : bindings}>;`,
    `export default ${name};`
  ].join("\n")}\n`;
}

function hostedPropsType({ name, host, overlay }: {
  name: string;
  host: ReturnType<typeof hostOf>;
  overlay: ReturnType<typeof overlayOf>;
}) {
  const isItemsHosted = host !== undefined;
  if (isItemsHosted) {
    return `${host.props}<Item, ${name}ComponentProps>`;
  }

  const isOverlay = overlay !== undefined;
  return isOverlay ? `${overlay.props}<${name}ComponentProps>` : `${name}ComponentProps`;
}

// An object whose members read and write the component's bindable props, to
// hand to code that cannot reach the props themselves.
function bagOf(keys: string[]) {
  const members = keys.map(
    key => `    get ${key}() {\n      return ${key};\n    },\n    set ${key}(next) {\n      ${key} = next;\n    }`
  );
  return keys.length === 0 ? "{}" : `{\n${members.join(",\n")}\n  }`;
}

function hostConnectLines({ name, host }: {
  name: string;
  host: NonNullable<ReturnType<typeof hostOf>>;
}) {
  return [
    "",
    `  function connect(native: ${name}) {`,
    `    const disconnectProperties = connect${name}(native, rest, bound);`,
    `    const items = ${host.attach};`,
    ...host.hasHandle ? ["    handle = items.handle;"] : [],
    "    return () => {",
    "      items.dispose();",
    "      disconnectProperties();",
    "    };",
    "  }"
  ];
}

function overlayConnectLines({ name, overlay }: {
  name: string;
  overlay: NonNullable<ReturnType<typeof overlayOf>>;
}) {
  return [
    "",
    `  function connect(placed: PlacedControl<${name}>) {`,
    `    const disconnectProperties = connect${name}(placed.control, rest, bound);`,
    `    const overlay = ${overlay.attach}({ placed, props: rest, bound });`,
    "    return () => {",
    "      overlay.dispose();",
    "      disconnectProperties();",
    "    };",
    "  }"
  ];
}

// The classes whose attached properties a snippet of the level fills: the
// renderer sets them through the class's tag.
function attachedSlotOwners(level: ClassModel) {
  const owners = new Map<string, TypeName>();
  for (const attached of chain(level).flatMap(entry => entry.attached.filter(candidate => candidate.isSlot))) {
    owners.set(attached.owner.name, attached.owner);
  }

  return [...owners.values()];
}

// The classes a component registers: its own, the collections it can be an
// item of, and the owners of the attached properties it sets by snippet.
function registeredClasses(level: ClassModel) {
  const classes = [level.type, ...level.registers, ...attachedSlotOwners(level)];
  return new Map(classes.map(type => [type.name, type]));
}

function destructuredProps({ bindables, hasHandle, hasChildren, constructedKeys }: {
  bindables: string[];
  hasHandle: boolean;
  hasChildren: boolean;
  constructedKeys: string[];
}) {
  return [
    ...constructedKeys,
    ...bindables.map(key => `${key} = $bindable()`),
    ...hasHandle ? ["handle = $bindable()"] : [],
    ...hasChildren ? ["children"] : [],
    "class: className",
    "style",
    "...rest"
  ];
}

// Never self-closed: Svelte warns that `<tag />` is ambiguous for an element
// that is not void, which every custom element is.
function elementMarkup({ open, tag, inner }: {
  open: string;
  tag: string;
  inner: string[];
}) {
  const isEmpty = inner.length === 0;
  return isEmpty
    ? `${open}></${tag}>`
    : `${open}>\n${inner.map(line => `  ${line}`).join("\n")}\n</${tag}>`;
}

// The class a component registers in place of its own, made ready from props.
function constructedValue({ type, constructed }: {
  type: TypeName;
  constructed: NonNullable<ReturnType<typeof constructedClasses.get>>;
}) {
  const keys = constructed.keys.map(key => `${key}: untrack(() => ${key})`);
  const xamlName = constructed.isMadeByXaml ? [`xamlName: "${type.name}"`] : [];
  return `${constructed.helper}({ ${[`type: ${type.name}`, ...xamlName, ...keys].join(", ")} })`;
}

function registerControlsLine({ level, registered }: {
  level: ClassModel;
  registered: Map<string, TypeName>;
}) {
  const entries = [...registered.values()].map(type => {
    const isOwn = type === level.type;
    const tag = isOwn ? level.tag : kebabCase(type.name);
    const constructed = isOwn ? constructedClasses.get(type.name) : undefined;
    const value = constructed === undefined ? type.name : constructedValue({
      type,
      constructed
    });
    return `"${tag}": ${value}`;
  });
  return `  registerControls({ ${entries.join(", ")} });`;
}

export function emitComponent(level: ClassModel) {
  const name = level.type.name;
  const host = hostOf(name);
  const isHosted = host !== undefined;
  const hasHandle = isHosted && host.hasHandle;
  const overlay = overlayOf(name);
  const isOverlay = overlay !== undefined;
  const hasChildren = (level.contentProperty !== null || holdsItems(level)) && !isHosted;
  const bindables = componentBindableNames(level);
  const constructed = constructedClasses.get(name);
  const destructured = destructuredProps({
    bindables,
    hasHandle,
    hasChildren,
    constructedKeys: constructed?.keys ?? []
  });
  const bound = bagOf(bindables);
  const connect = isHosted ? "connect(native)" : `connect${name}(native, rest, bound)`;
  const attachment = isOverlay
    ? `{@attach placedControl((placed: PlacedControl<${name}>) => untrack(() => connect(placed)))}`
    : `{@attach control((native: ${name}) => untrack(() => ${connect}))}`;
  const open = `<${level.tag} {...attachmentsOf(rest)} class={className} {style} ${attachment}`;
  const inner = slotMarkup({
    level,
    bindables,
    isHosted,
    owned: host?.owned ?? []
  });
  const isSnippetUsed = inner.some(line => line.includes("isSnippet("));
  const markup = elementMarkup({
    open,
    tag: level.tag,
    inner
  });
  const propsType = hostedPropsType({
    name,
    host,
    overlay
  });
  const registered = registeredClasses(level);
  const runtimeNames = [
    "attachmentsOf",
    isOverlay ? "placedControl" : "control",
    ...isSnippetUsed ? ["isSnippet"] : [],
    "registerControls"
  ];
  return `${[
    SVELTE_HEADER,
    isHosted ? "<script generics=\"Item\" lang=\"ts\">" : "<script lang=\"ts\">",
    "  import { untrack } from \"svelte\";",
    `  import { ${sorted(registered.keys()).join(", ")} } from "./bindings.ts";`,
    ...isHosted ? [
      `  import { ${host.imports.join(", ")} } from "${ITEMS_FOLDER}/${host.module}";`,
      `  import type { ${host.props} } from "${ITEMS_FOLDER}/items-props.ts";`
    ] : [],
    ...isOverlay ? [
      `  import { ${overlay.attach} } from "${OVERLAY_FOLDER}/overlay-host.svelte.ts";`,
      `  import type { ${overlay.props} } from "${OVERLAY_FOLDER}/overlay-props.ts";`,
      `  import type { PlacedControl } from "${sharedRoot(level)}../runtime.ts";`
    ] : [],
    `  import { ${runtimeNames.join(", ")} } from "${sharedRoot(level)}../runtime.ts";`,
    ...constructed === undefined ? [] : [`  import { ${constructed.helper} } from "${sharedRoot(level)}../constructed.ts";`],
    `  import type { ${name}ComponentProps } from "./controls/${name}.svelte.ts";`,
    `  import { connect${name} } from "./controls/${name}.svelte.ts";`,
    "",
    `  let { ${destructured.join(", ")} }: ${propsType} = $props();`,
    `  const bound = ${bound};`,
    registerControlsLine({
      level,
      registered
    }),
    ...isHosted ? hostConnectLines({
      name,
      host
    }) : [],
    ...isOverlay ? overlayConnectLines({
      name,
      overlay
    }) : [],
    "</script>",
    "",
    markup
  ].join("\n")}\n`;
}

const OWN_PROPERTY_LIMIT = 8;
const NAMESPACE_PREFIX = "Microsoft.UI.Xaml.";
const WINUI_DOCS_URL = "https://learn.microsoft.com/windows/windows-app-sdk/api/winrt";
const WIN2D_NAMESPACE = "Microsoft.Graphics.Canvas";
const WIN2D_DOCS_URL = "https://microsoft.github.io/Win2D/WinUI3/html";

function docsUrlOf(type: {
  namespace: string;
  name: string;
}) {
  const isWin2d = type.namespace.startsWith(WIN2D_NAMESPACE);
  if (isWin2d) {
    return `${WIN2D_DOCS_URL}/T_${type.namespace.replaceAll(".", "_")}_${type.name}.htm`;
  }

  return `${WINUI_DOCS_URL}/${type.namespace}.${type.name}`.toLowerCase();
}

function codeList(names: string[]) {
  return names.map(name => `\`${name}\``).join(", ");
}

// The README's table of the components: one row for each, with the props its
// class adds (the rest come from the classes it inherits from) and the
// bindables it has, inherited ones included.
export function emitControlsTable(model: Model) {
  const rows = model.classes.filter(level => level.isComponent).map(level => {
    const own = level.properties.map(property => property.key);
    const shown = codeList(own.slice(0, OWN_PROPERTY_LIMIT));
    const hiddenCount = own.length - OWN_PROPERTY_LIMIT;
    const props = hiddenCount > 0 ? `${shown}, +${hiddenCount} more` : shown;
    const category = level.type.namespace.replace(NAMESPACE_PREFIX, "");
    const hasContent = level.contentProperty !== null || holdsItems(level);
    const content = hasContent ? "yes" : "";
    return `| [\`${level.type.name}\`](${docsUrlOf(level.type)}) | ${category} | ${props} | ${codeList(componentBindableNames(level))} | ${content} |`;
  });
  return [
    "| Component | Namespace | Props it adds | Bindable | Children |",
    "| --- | --- | --- | --- | --- |",
    ...rows
  ].join("\n");
}

export function emitIndex(model: Model) {
  const components = model.classes.filter(level => level.isComponent);
  const lines = [GENERATED_HEADER, ""];
  for (const component of components) {
    const name = component.type.name;
    lines.push(`export { default as ${name} } from "./${name}.svelte";`);
    lines.push(`export type { ${name}ComponentProps } from "./${name}.d.svelte.ts";`);
  }

  return `${lines.join("\n")}\n`;
}

// Every component's props through StrictProps (src/components/strictness.ts):
// tsc fails here on a prop typed any or unknown, naming it.
export function emitStrictness(model: Model) {
  const names = model.classes.filter(level => level.isComponent).map(level => level.type.name);
  const lines = [
    GENERATED_HEADER,
    "",
    `import type { Expect, StrictProps } from "${model.folder === "" ? "" : "../"}../strictness.ts";`,
    `import type { ${names.map(name => `${name}ComponentProps`).join(", ")} } from "./index.ts";`,
    "",
    "export type PropsStrictness = [",
    ...names.map(name => `  Expect<StrictProps<"${name}", ${name}ComponentProps>>,`),
    "];"
  ];
  return `${lines.join("\n")}\n`;
}

function quoted(values: string[]) {
  return `[${values.map(value => JSON.stringify(value)).join(", ")}]`;
}

export function emitMetadata(model: Model) {
  // WebStorm reads these strings as TypeScript (they begin with `export`) and
  // flags the type `LevelMetadata`, which they define in another string.
  // noinspection JSUnresolvedReference
  const lines = [
    GENERATED_HEADER,
    "",
    "// What each level of the hierarchy adds, and the facts a renderer or a test needs about a component.",
    "export interface LevelMetadata {",
    "  parent: string | null;",
    "  properties: string[];",
    "  events: string[];",
    "  // Each attached prop and the static [owner, setter] it calls.",
    "  attached: Record<string, [string, string]>;",
    "  bindables: string[];",
    "  // Read-only state the control gives back one-way, bound the same way.",
    "  observed: string[];",
    "  contentProperty: string | null;",
    "  isComponent: boolean;",
    "  tag: string;",
    "  namespace: string;",
    "}",
    "",
    "export const levels: Record<string, LevelMetadata> = {"
  ];
  const levelBlocks = model.classes.map(level => [
    `  ${level.type.name}: {`,
    `    parent: ${level.parent === null ? "null" : JSON.stringify(level.parent.type.name)},`,
    `    properties: ${quoted(level.properties.map(property => property.key))},`,
    `    events: ${quoted(level.events.map(event => event.key))},`,
    `    attached: {${level.attached.map(attached => `\n      ${attached.key}: ${quoted([attached.owner.name, attached.setter])}`).join(",")}${level.attached.length === 0 ? "" : "\n    "}},`,
    `    bindables: ${quoted(level.bindables.map(bindable => bindable.key))},`,
    `    observed: ${quoted(level.observed.map(observed => observed.key))},`,
    `    contentProperty: ${level.contentProperty === null ? "null" : JSON.stringify(level.contentProperty)},`,
    `    isComponent: ${level.isComponent},`,
    `    tag: ${JSON.stringify(level.tag)},`,
    `    namespace: ${JSON.stringify(level.type.namespace)}`,
    "  }"
  ].join("\n"));
  lines.push(levelBlocks.join(",\n"), "};", "", "export const excluded: Record<string, string> = {");
  lines.push(model.excluded.map(entry => `  ${JSON.stringify(entry.name)}: ${JSON.stringify(entry.reason)}`).join(",\n"));
  lines.push("};");
  return `${lines.join("\n")}\n`;
}
